const nextStage = ($json.drip_stage || 0) + 1; // 1, 2 or 3
const tplName = $env['DRIP_TEMPLATE_' + nextStage];
const lang = $env.DRIP_TEMPLATE_LANG || 'en';
const body = {
  messaging_product: 'whatsapp',
  to: $json.wa_id,
  type: 'template',
  template: { name: tplName, language: { code: lang } }
};
return { json: { templateBody: body, leadId: $json.id, nextStage, templateName: tplName } };

const res = $json.body || $json;
const nextStage = $('Build Template Body').item.json.nextStage;
const leadId = $('Build Template Body').item.json.leadId;
let status = 'sent';
let errCode = '';
let msgId = '';
if (res && res.error) {
  errCode = String(res.error.code || '');
  // 131049 is Meta's per-user marketing frequency cap. Not a fault. Retry next cycle.
  status = errCode === '131049' ? 'freqcap' : 'error';
} else if (res && res.messages && res.messages[0]) {
  msgId = res.messages[0].id;
}
return { json: { leadId, nextStage, status, errCode, msgId } };
